1	import {
2	  ChatConfig,
3	  ConvTemplateConfig,
4	  MessagePlaceholders,
5	  Role,
6	} from "./config";
7	import {
8	  ChatCompletionContentPart,
9	  ChatCompletionContentPartImage,
10	  ChatCompletionMessageParam,
11	  ChatCompletionRequest,
12	} from "./openai_api_protocols/index";
13	import {
14	  ContentTypeError,
15	  FunctionNotFoundError,
16	  InvalidToolChoiceError,
17	  MessageOrderError,
18	  MultipleTextContentError,
19	  SystemMessageOrderError,
20	  TextCompletionConversationError,
21	  TextCompletionConversationExpectsPrompt,
22	  UnsupportedRoleError,
23	  UnsupportedToolChoiceTypeError,
24	  UnsupportedToolTypeError,
25	} from "./error";
26	
27	type ImageURL = ChatCompletionContentPartImage.ImageURL;
28	
29	/**
30	 * Helper to keep track of history conversations.
31	 */
32	export class Conversation {
33	  // NOTE: Update `compareConversationObject()` whenever a new state is introduced.
34	  /** Each message is a tuple of (Role, role_name_str, message), where message can be either a
35	   *  string or an array of contentPart for possible image input.
36	   */
37	  public messages: Array<
38	    [Role, string, string | Array<ChatCompletionContentPart> | undefined]
39	  > = [];
40	  readonly config: ConvTemplateConfig;
41	
42	  /** Whether the Conversation object is for text completion with no conversation-style formatting */
43	  public isTextCompletion: boolean;
44	  /** Used when isTextCompletion is true */
45	  public prompt: string | undefined;
46	
47	  public function_string = "";
48	  public use_function_calling = false;
49	  public override_system_message?: string = undefined;
50	
51	  /**
52	   * Tracks whether the last message is an empty thinking block. Should only
53	   * be true when we are in the middle of a generation. Will be set to
54	   * false when the reply is finished with `finishReply()`.
55	   */
56	  private isLastMessageEmptyThinkingReplyHeader = false;
57	
58	  // TODO(tvm-team) confirm and remove
59	  // private contextWindowStart = 0;
60	
61	  constructor(config: ConvTemplateConfig, isTextCompletion = false) {
62	    this.config = config;
63	    this.isTextCompletion = isTextCompletion;
64	  }
65	
66	  // TODO: Consider rewriting this method, a bit messy.
67	  private getPromptArrayInternal(
68	    addSystem: boolean,
69	    startPos: number,
70	    config?: ChatConfig,
71	  ): Array<string | Array<string | ImageURL>> {
72	    if (this.config.seps.length == 0) {
73	      throw Error("Need seps to work");
74	    }
75	
76	    // Prepare system message
77	    // Get overridden system message if exists, else use default one in config
78	    let system_message = this.config.system_message;
79	    if (this.override_system_message !== undefined) {
80	      system_message = this.override_system_message;
81	    }
82	    const system_prompt = this.config.system_template.replace(
83	      MessagePlaceholders.system,
84	      system_message,
85	    );
86	    const ret: Array<string | Array<string | ImageURL>> =
87	      addSystem && system_prompt !== "" ? [system_prompt] : [];
88	
89	    // Process each message in this.messages
90	    for (let i = startPos; i < this.messages.length; ++i) {
91	      const item = this.messages[i];
92	      const role = item[0];
93	      const role_str = item[1];
94	      const messageContent = item[2];
95	
96	      // 1. Message from `appendReplyHeader()`, message is empty; not much processing is needed.
97	      if (messageContent === undefined) {
98	        if (i !== this.messages.length - 1) {
99	          throw new Error(
100	            "InternalError: Only expect message to be undefined for last " +
101	              "message for a reply header.",
102	          );
103	        }
104	        // Add ": " if there is no such field. If "", do not add sep
105	        const empty_sep =
106	          this.config.role_empty_sep || this.config.role_empty_sep == ""
107	            ? this.config.role_empty_sep
108	            : ": ";
109	        ret.push(role_str + empty_sep);
110	        continue;
111	      }
112	
113	      // 2. Message from `appendEmptyThinkingReplyHeader()`, message is an empty thinking block.
114	      if (
115	        this.isLastMessageEmptyThinkingReplyHeader &&
116	        i === this.messages.length - 1
117	      ) {
118	        // TODO(Charlie): content_sep or empty_sep? For Qwen3, both are "\n".
119	        const content_sep =
120	          this.config.role_content_sep || this.config.role_content_sep == ""
121	            ? this.config.role_content_sep
122	            : ": ";
123	        ret.push(role_str + content_sep + messageContent);
124	        continue;
125	      }
126	
127	      // 3. Each messageContent consists of one textPart, and >= 0 imageParts, regardless whether
128	      // it is Array<ChatCompletionContentPart> or text message. So we extract out each.
129	      let textContentPart = ""; // if no textPart, use an empty string
130	      const imageContentParts: ImageURL[] = [];
131	      if (Array.isArray(messageContent)) {
132	        // 2.1 content is Array<ChatCompletionContentPart>
133	        // Iterate through the contentParts, get the text and list of images. There should
134	        // be only a single text. TODO: is it always the case the number of textContentPart <= 1?
135	        let seenText = false;
136	        for (let i = 0; i < messageContent.length; i++) {
137	          const curContentPart = messageContent[i];
138	          if (curContentPart.type === "text") {
139	            if (seenText) {
140	              throw new MultipleTextContentError();
141	            }
142	            textContentPart = curContentPart.text;
143	            seenText = true;
144	          } else {
145	            imageContentParts.push(curContentPart.image_url);
146	          }
147	        }
148	      } else {
149	        // 2.2 content is just a string
150	        textContentPart = messageContent;
151	      }
152	
153	      // 3. Format textContentPart with role and sep to get message_str and role_prefix
154	      let message_str;
155	      let role_prefix;
156	      if (this.config.role_templates !== undefined) {
157	        message_str = this.config.role_templates[role]?.replace(
158	          MessagePlaceholders[Role[role] as keyof typeof MessagePlaceholders],
159	          textContentPart,
160	        );
161	        if (this.use_function_calling && this.function_string !== "") {
162	          message_str = message_str?.replace(
163	            MessagePlaceholders.function,
164	            this.function_string,
165	          );
166	        }
167	        message_str = message_str?.replace(MessagePlaceholders.function, "");
168	      }
169	
170	      if (message_str == undefined) {
171	        message_str = textContentPart;
172	      }
173	      if (
174	        this.config.add_role_after_system_message === false &&
175	        system_prompt != "" &&
176	        i == 0
177	      ) {
178	        role_prefix = "";
179	      } else {
180	        // Add ": " if there is no such field. If "", do not add sep
181	        const content_sep =
182	          this.config.role_content_sep || this.config.role_content_sep == ""
183	            ? this.config.role_content_sep
184	            : ": ";
185	        role_prefix = role_str + content_sep;
186	      }
187	
188	      // 4. Combine everything together
189	      if (imageContentParts.length === 0) {
190	        // If no image, just a single string to represent this message
191	        ret.push(
192	          role_prefix +
193	            message_str +
194	            this.config.seps[i % this.config.seps.length],
195	        );
196	      } else {
197	        // Per-model image layout
198	        const curMessageList: Array<string | ImageURL> = [role_prefix];
199	        const modelType = config?.model_type ?? "";
200	        imageContentParts.forEach((curImage: ImageURL) => {
201	          if (modelType === "phi3_v") {
202	            curMessageList.push(curImage);
203	            curMessageList.push("\n");
204	          } else {
205	            curMessageList.push(curImage);
206	          }
207	        });
208	        curMessageList.push(
209	          message_str + this.config.seps[i % this.config.seps.length],
210	        );
211	        ret.push(curMessageList);
212	      }
213	    }
214	    return ret;
215	  }
216	
217	  /**
218	   * Get prompt arrays with the first one as system.
219	   *
220	   * It is returned as an array of `string | Array<string | ImageURL>`, where each element of
221	   * the array represents the formatted message of a role/turn. If the message only contains text,
222	   * it will be a string that concatenates the role string, message, and separators. If the
223	   * message contains image(s), it will be an array of string and ImageURL in the order of which
224	   * they will be prefilled into the model. e.g. it can be something like
225	   * [
226	   *   "<|system|>\nSome system prompt\n",
227	   *   [
228	   *     "<|user|>\n",
229	   *     imageURL1,
230	   *     "\n",
231	   *     imageURL2,
232	   *     "\n",
233	   *     "Some user input<|end|>\n"
234	   *   ],
235	   * ]
236	   *
237	   * @returns The prompt array.
238	   */
239	  getPromptArray(
240	    config?: ChatConfig,
241	  ): Array<string | Array<string | ImageURL>> {
242	    if (this.isTextCompletion) {
243	      throw new TextCompletionConversationError("getPromptArray");
244	    }
245	    return this.getPromptArrayInternal(true, 0, config);
246	  }
247	
248	  /**
249	   * Get the last round of prompt has not been fed as input.
250	   *
251	   * @note This function needs to be used with the assumption that
252	   *       the caller call appendMessage then appendReplyHeader.
253	   *
254	   * @returns The prompt array.
255	   */
256	  getPromptArrayLastRound(config?: ChatConfig) {
257	    if (this.isTextCompletion) {
258	      throw new TextCompletionConversationError("getPromptArrayLastRound");
259	    }
260	    if (this.messages.length < 3) {
261	      throw Error("needs to call getPromptArray for the first message");
262	    }
263	    return this.getPromptArrayInternal(false, this.messages.length - 2, config);
264	  }
265	
266	  /**
267	   * Return prompt in an array for non-conversation text completion.
268	   */
269	  getPromptArrayTextCompletion(): Array<string> {
270	    if (!this.isTextCompletion || this.prompt === undefined) {
271	      throw new TextCompletionConversationExpectsPrompt();
272	    }
273	    return [this.prompt];
274	  }
275	
276	  /**
277	   * Resets all states for this.conversation.
278	   */
279	  reset() {
280	    // Note: Update this whenever we introduce a new state to conversation.
281	    this.messages = [];
282	    this.override_system_message = undefined;
283	    this.function_string = "";
284	    this.use_function_calling = false;
285	    this.isTextCompletion = false;
286	    this.prompt = undefined;
287	  }
288	
289	  getStopStr(): string[] {
290	    // TODO(Charlie): Is this needed?
291	    // if (this.config.stop_str.length > 0) {
292	    //   return this.config.stop_str;
293	    // }
294	    // return [this.config.seps[this.config.seps.length - 1]];
295	    return this.config.stop_str;
296	  }
297	
298	  getStopTokens() {
299	    return this.config.stop_token_ids;
300	  }
301	
302	  appendMessage(
303	    role: Role,
304	    message: string | Array<ChatCompletionContentPart>,
305	    role_name?: string,
306	  ) {
307	    if (this.isTextCompletion) {
308	      throw new TextCompletionConversationError("appendMessage");
309	    }
310	    if (
311	      this.messages.length != 0 &&
312	      this.messages[this.messages.length - 1][2] == undefined
313	    ) {
314	      throw Error("Have unfinished reply");
315	    }
316	    if (!(role in this.config.roles)) {
317	      throw Error("Role is not supported: " + role);
318	    }
319	    const role_name_str = role_name ? role_name : this.config.roles[role];
320	    this.messages.push([role, role_name_str, message]);
321	  }
322	
323	  appendReplyHeader(role: Role) {
324	    if (this.isTextCompletion) {
325	      throw new TextCompletionConversationError("appendReplyHeader");
326	    }
327	    if (!(role in this.config.roles)) {
328	      throw Error("Role is not supported: " + role);
329	    }
330	    this.messages.push([role, this.config.roles[role], undefined]);
331	  }
332	
333	  appendEmptyThinkingReplyHeader(role: Role, emptyThinkingBlockStr: string) {
334	    if (this.isTextCompletion) {
335	      throw new TextCompletionConversationError(
336	        "appendEmptyThinkingReplyHeader",
337	      );
338	    }
339	    this.isLastMessageEmptyThinkingReplyHeader = true;
340	    this.messages.push([role, this.config.roles[role], emptyThinkingBlockStr]);
341	  }
342	
343	  finishReply(message: string) {
344	    if (this.isTextCompletion) {
345	      throw new TextCompletionConversationError("finishReply");
346	    }
347	    if (this.messages.length == 0) {
348	      throw Error("Message error should not be 0");
349	    }
350	    if (
351	      this.messages[this.messages.length - 1][2] !== undefined &&
352	      // If the last message has an empty thinknig block, last message is expected
353	      // to be non-empty.
354	      this.isLastMessageEmptyThinkingReplyHeader === false
355	    ) {
356	      throw Error("Already assigned");
357	    }
358	    this.messages[this.messages.length - 1][2] = message;
359	    this.isLastMessageEmptyThinkingReplyHeader = false;
360	  }
361	}
362	
363	export function getConversation(
364	  conv_template: ConvTemplateConfig,
365	  conv_config?: Partial<ConvTemplateConfig>,
366	  isTextCompletion = false,
367	): Conversation {
368	  return new Conversation(
369	    { ...conv_template, ...conv_config },
370	    isTextCompletion,
371	  );
372	}
373	
374	/**
375	 * Compare the states of two conversation instances. Equality is defined as their getPromptArray()
376	 * should return the exact same things, which is determined by fields: messages, function_string,
377	 * use_function_calling, and override_system_message.
378	 *
379	 * @returns True if `convA` equals to `convB`
380	 * @note We assume convA and convB has the same `this.config`.
381	 */
382	export function compareConversationObject(
383	  convA: Conversation,
384	  convB: Conversation,
385	): boolean {
386	  // NOTE: Update this function whenever a new state is introduced to `Conversation`.
387	  // Check the easy ones first
388	  if (
389	    convA.function_string !== convB.function_string ||
390	    convA.use_function_calling !== convB.use_function_calling ||
391	    convA.override_system_message !== convB.override_system_message ||
392	    convA.messages.length !== convB.messages.length ||
393	    convA.isTextCompletion !== convB.isTextCompletion
394	  ) {
395	    return false;
396	  }
397	
398	  // Then check message
399	  if (convA.messages.length === 0 && convB.messages.length === 0) {
400	    // both are empty
401	    return true;
402	  }
403	  if (convA.messages.length !== convB.messages.length) {
404	    // different number of messages
405	    return false;
406	  }
407	
408	  const msgLen = convA.messages.length;
409	  const msgEntryLen = convA.messages[0].length; // always 3 for now
410	  for (let i = 0; i < msgLen; i++) {
411	    for (let j = 0; j < msgEntryLen; j++) {
412	      const entryA = convA.messages[i][j];
413	      const entryB = convB.messages[i][j];
414	      if (typeof entryA === "string" && typeof entryB === "string") {
415	        // Case 1: both are strings
416	        if (convA.messages[i][j] !== convB.messages[i][j]) {
417	          return false;
418	        }
419	      } else if (entryA === undefined && entryB === undefined) {
420	        // Case 2: both undefined
421	        continue;
422	      } else if (Array.isArray(entryA) && Array.isArray(entryB)) {
423	        // Case 3: both are ChatCompletionContentPart[]
424	        if (entryA.length !== entryB.length) {
425	          return false;
426	        }
427	        const numContentParts = entryA.length;
428	        for (let k = 0; k < numContentParts; k++) {
429	          const entryA_k = entryA[k];
430	          const entryB_k = entryB[k];
431	          if (entryA_k.type === "text" && entryB_k.type === "text") {
432	            // Case 3.1: both are text
433	            if (entryA_k.text !== entryB_k.text) {
434	              return false;
435	            }
436	          } else if (
437	            entryA_k.type === "image_url" &&
438	            entryB_k.type === "image_url"
439	          ) {
440	            // Case 3.2: both are image_url
441	            if (
442	              entryA_k.image_url.url !== entryB_k.image_url.url ||
443	              entryA_k.image_url.detail !== entryB_k.image_url.detail
444	            ) {
445	              return false;
446	            }
447	          } else {
448	            // Case 3.3: of different type
449	            return false;
450	          }
451	        }
452	      } else {
453	        // Case 4: two entries are of different types
454	        return false;
455	      }
456	    }
457	  }
458	  return true;
459	}
460	
461	/**
462	 * Get a new Conversation object based on the chat completion request.
463	 *
464	 * @param request The incoming ChatCompletionRequest
465	 * @param includeLastMsg Include last message, by default is false. Set to true for testing only.
466	 * @note By default, `request.messages[-1]` is not included as it would be treated as a normal
467	 * input to `prefill()`.
468	 */
469	export function getConversationFromChatCompletionRequest(
470	  request: ChatCompletionRequest,
471	  config: ChatConfig,
472	  includeLastMsg = false,
473	): Conversation {
474	  // 0. Instantiate a new Conversation object
475	  const conversation = getConversation(
476	    config.conv_template,
477	    config.conv_config,
478	  );
479	
480	  // 1. Populate function-calling-related fields
481	  // TODO: either remove these or support gorilla-like function calling models.
482	  // These commented code was used to support gorilla, but we could not use grammar to
483	  // guarantee its output, nor make it conform to OpenAI's function calling output. Kept for now.
484	  // const functionCallUsage = this.getFunctionCallUsage(request);
485	  // conversation.function_string = functionCallUsage;
486	  // conversation.use_function_calling = functionCallUsage !== "";
487	
488	  // 2. Populate conversation.messages
489	  const input = request.messages;
490	  const lastId = input.length - 1;
491	  if (input[lastId].role !== "user" && input[lastId].role !== "tool") {
492	    throw new MessageOrderError(
493	      "The last message should be from the `user` or `tool`.",
494	    );
495	  }
496	  const iterEnd = includeLastMsg ? input.length : input.length - 1;
497	  for (let i = 0; i < iterEnd; i++) {
498	    const message: ChatCompletionMessageParam = input[i];
499	    if (message.role === "system") {
500	      if (i !== 0) {
501	        throw new SystemMessageOrderError();
502	      }
503	      conversation.override_system_message = message.content;
504	    } else if (message.role === "user") {
505	      conversation.appendMessage(Role.user, message.content, message.name);
506	    } else if (message.role === "assistant") {
507	      if (typeof message.content !== "string") {
508	        throw new ContentTypeError(message.role + "'s message");
509	      }
510	      conversation.appendMessage(Role.assistant, message.content, message.name);
511	    } else if (message.role === "tool") {
512	      conversation.appendMessage(Role.tool, message.content);
513	    } else {
514	      // Use `["role"]` instead of `.role` to suppress "Property does not exist on type 'never'"
515	      throw new UnsupportedRoleError(message["role"]);
516	    }
517	  }
518	  return conversation;
519	}
520	
521	/**
522	 * Returns the function string based on the request.tools and request.tool_choice, raises erros if
523	 * encounter invalid request.
524	 *
525	 * @param request The chatCompletionRequest we are about to prefill for.
526	 * @returns The string used to set Conversation.function_string
527	 */
528	export function getFunctionCallUsage(request: ChatCompletionRequest): string {
529	  if (
530	    request.tools == undefined ||
531	    (typeof request.tool_choice == "string" && request.tool_choice == "none")
532	  ) {
533	    return "";
534	  }
535	  if (
536	    typeof request.tool_choice == "string" &&
537	    request.tool_choice !== "auto"
538	  ) {
539	    throw new InvalidToolChoiceError(request.tool_choice);
540	  }
541	  if (
542	    typeof request.tool_choice !== "string" &&
543	    request.tool_choice?.type !== "function"
544	  ) {
545	    throw new UnsupportedToolChoiceTypeError();
546	  }
547	
548	  const singleFunctionToCall =
549	    typeof request.tool_choice !== "string" &&
550	    request.tool_choice?.function?.name;
551	  if (singleFunctionToCall) {
552	    for (const f of request.tools) {
553	      if (singleFunctionToCall == f.function.name) {
554	        return JSON.stringify([f.function]);
555	      }
556	    }
557	    throw new FunctionNotFoundError(singleFunctionToCall);
558	  }
559	
560	  const function_list = [];
561	  for (const f of request.tools) {
562	    if (f.type !== "function") {
563	      throw new UnsupportedToolTypeError();
564	    }
565	    function_list.push(f.function);
566	  }
567	  return JSON.stringify(function_list);
568	}
